import{_ as s,o as n,c as o,ag as r}from"./chunks/framework.KxDd3USm.js";const i=JSON.parse('{"title":"03.2 需求分析与软件设计 ★","description":"","frontmatter":{},"headers":[],"relativePath":"03-软件工程基础/02-需求分析与软件设计.md","filePath":"03-软件工程基础/02-需求分析与软件设计.md"}'),a={name:"03-软件工程基础/02-需求分析与软件设计.md"};function d(g,t,p,e,l,h){return n(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="_03-2-需求分析与软件设计-★" tabindex="-1">03.2 需求分析与软件设计 ★ <a class="header-anchor" href="#_03-2-需求分析与软件设计-★" aria-label="Permalink to &quot;03.2 需求分析与软件设计 ★&quot;">​</a></h1><h3 id="_2-1-需求工程的四个过程" tabindex="-1">2.1 需求工程的四个过程 <a class="header-anchor" href="#_2-1-需求工程的四个过程" aria-label="Permalink to &quot;2.1 需求工程的四个过程&quot;">​</a></h3><p><strong>需求获取 → 需求分析 → 需求规格说明（定义）→ 需求验证（确认）</strong>（背顺序）。</p><p><strong>需求分析的任务是&quot;找出系统要实现什么功能&quot;</strong>——只回答<strong>做什么</strong>，不回答<strong>怎么做</strong>。所以&quot;确定模块内部算法&quot;&quot;设计数据库表结构&quot;都<strong>不属于</strong>需求分析（属于设计阶段），这是真题的一种问法。</p><p><strong>需求验证</strong>指检查需求规格说明书是否<strong>正确、一致、完整</strong>（三个词连读记）。</p><h3 id="_2-2-需求的分类-两个层次-别混" tabindex="-1">2.2 需求的分类（两个层次，别混） <a class="header-anchor" href="#_2-2-需求的分类-两个层次-别混" aria-label="Permalink to &quot;2.2 需求的分类（两个层次，别混）&quot;">​</a></h3><p><strong>按抽象层次分三层</strong>：</p><table tabindex="0"><thead><tr><th>层次</th><th>视角</th><th>例子</th></tr></thead><tbody><tr><td><strong>业务需求</strong></td><td>整体（组织为什么做这个系统）</td><td>&quot;提升线上订单占比到 60%&quot;</td></tr><tr><td><strong>用户需求</strong></td><td>用户视角（用户想干什么）</td><td>&quot;我要能在线查订单进度&quot;</td></tr><tr><td><strong>系统需求</strong></td><td>计算机化视角（机器怎么界定）</td><td>见下面三类</td></tr></tbody></table><p><strong>系统需求内部再分三类</strong>（这一层才是选择题的主战场）：</p><table tabindex="0"><thead><tr><th>类别</th><th>含义</th><th>识别特征</th><th>例子</th></tr></thead><tbody><tr><td><strong>功能需求</strong></td><td>系统<strong>做什么</strong></td><td>动词 + 对象（查询、统计、导出）</td><td>&quot;系统应能按日期导出销售报表&quot;</td></tr><tr><td><strong>性能需求</strong>（非功能需求）</td><td>做得<strong>怎么样</strong></td><td>含<strong>数字指标</strong>：响应时间、吞吐量、并发数、可靠性</td><td>&quot;响应时间不超过 2 秒&quot;</td></tr><tr><td><strong>设计约束</strong></td><td><strong>必须遵守</strong>的外部条件</td><td>&quot;必须用…&quot;&quot;必须符合…标准&quot;</td><td>&quot;必须部署在国产操作系统上&quot;&quot;须符合等保三级&quot;</td></tr></tbody></table><p><strong>应试动作</strong>：判断口诀——<strong>有数字的&quot;多快好省&quot;归性能，有&quot;必须/须符合&quot;的归设计约束，其余动词句归功能需求</strong>。</p><h3 id="_2-3-结构化分析的产出-四件套-必背清单" tabindex="-1">2.3 结构化分析的产出：四件套（必背清单） <a class="header-anchor" href="#_2-3-结构化分析的产出-四件套-必背清单" aria-label="Permalink to &quot;2.3 结构化分析的产出：四件套（必背清单）&quot;">​</a></h3><p>结构化分析（SA）做完之后，交出来的东西是<strong>四件</strong>，考题常问&quot;下列不属于结构化分析结果的是&quot;：</p><table tabindex="0"><thead><tr><th>产出</th><th>作用</th><th>一句话</th></tr></thead><tbody><tr><td><strong>一套分层的数据流图（DFD）</strong></td><td><strong>功能建模</strong>——描述数据怎么流动、被怎么加工</td><td>&quot;系统的功能地图&quot;</td></tr><tr><td><strong>一本数据词典（DD）</strong></td><td>给 DFD 中每个数据流、数据存储、数据项下<strong>精确定义</strong></td><td>&quot;把图上的名字翻译成人能懂的定义&quot;</td></tr><tr><td><strong>一组小说明</strong>（加工逻辑说明）</td><td>描述 DFD 里每个<strong>加工内部</strong>的处理逻辑</td><td>&quot;加工肚子里的算法&quot;</td></tr><tr><td><strong>补充材料：E-R 图</strong></td><td>描述数据之间的关系</td><td>&quot;数据的静态结构&quot;</td></tr></tbody></table><p><strong>动机</strong>：为什么光有 DFD 不够？因为 DFD 里的&quot;订单&quot;&quot;客户信息&quot;只是<strong>名字</strong>，谁也不知道里面究竟有哪几个字段——<strong>没有数据词典，图中的名字就没有精确含义</strong>；同理 DFD 里的&quot;审核&quot;这个加工是个黑盒子，<strong>没有小说明就不知道它按什么规则审核</strong>。图 + 词典 + 说明，才是完整的一份分析结果。</p><h3 id="_2-4-软件设计的四项活动-顺序不能乱" tabindex="-1">2.4 软件设计的四项活动（顺序不能乱） <a class="header-anchor" href="#_2-4-软件设计的四项活动-顺序不能乱" aria-label="Permalink to &quot;2.4 软件设计的四项活动（顺序不能乱）&quot;">​</a></h3><p>需求想清楚了，进入设计。设计的四项活动是一条有先后依赖的链：</p><table tabindex="0"><thead><tr><th>活动</th><th>做什么</th><th>依据</th></tr></thead><tbody><tr><td><strong>① 体系结构设计</strong></td><td>定义软件系统<strong>各主要部件之间的关系</strong>（先搭骨架）</td><td>需求 + 经验</td></tr><tr><td><strong>② 数据设计</strong></td><td>基于 <strong>E-R 图</strong>确定<strong>文件系统结构与数据库表结构</strong></td><td>E-R 图</td></tr><tr><td><strong>③ 接口设计</strong>（人机界面设计）</td><td>软件<strong>内部</strong>、软件与<strong>操作系统</strong>间、软件与<strong>人</strong>之间如何通信</td><td>体系结构</td></tr><tr><td><strong>④ 过程设计</strong></td><td>把结构部件转换成<strong>过程描述</strong>——确定各部件<strong>内部的算法与内部数据结构</strong></td><td>前两项结果</td></tr></tbody></table><p><strong>考试问法</strong>：&quot;确定模块内部算法与数据结构属于哪个活动&quot;→ <strong>过程设计</strong>（不是体系结构设计，体系结构只管部件之间的关系）。&quot;基于 E-R 图确定表结构&quot;→ <strong>数据设计</strong>。</p><h3 id="_2-5-加工逻辑的三种描述工具-判定表是重点" tabindex="-1">2.5 加工逻辑的三种描述工具（判定表是重点） <a class="header-anchor" href="#_2-5-加工逻辑的三种描述工具-判定表是重点" aria-label="Permalink to &quot;2.5 加工逻辑的三种描述工具（判定表是重点）&quot;">​</a></h3><p>光有 DFD，加工内部是个黑盒；<strong>小说明</strong>就是用来&quot;打开黑盒&quot;的。描述工具<strong>三种</strong>：<strong>结构化语言、判定表、判定树</strong>。</p><p><strong>为什么需要判定表</strong>：当某个加工的一组动作<strong>依赖多个逻辑条件的取值组合</strong>时，用自然语言写必然又长又漏（&quot;如果是会员且金额够…如果是会员但金额不够…如果不是会员但金额够…&quot;），<strong>判定表能把条件组合与应做的动作一一对平，不漏一种组合</strong>。</p><p><strong>判定表的四个部分</strong>（用双线分割成四个区域）：</p><table tabindex="0"><thead><tr><th>区域</th><th>内容</th></tr></thead><tbody><tr><td>左上</td><td><strong>条件定义</strong></td></tr><tr><td>右上</td><td><strong>条件取值的组合</strong>（每一列 = 一条规则）</td></tr><tr><td>左下</td><td><strong>动作定义</strong></td></tr><tr><td>右下</td><td><strong>在各种取值组合下应执行的动作</strong></td></tr></tbody></table><p><strong>完整例子</strong>（打折规则：会员且金额≥200 打 9 折；金额≥200 或会员打 95 折；其余不打折）：</p><table tabindex="0"><thead><tr><th>条件 / 动作</th><th>规则 1</th><th>规则 2</th><th>规则 3</th><th>规则 4</th></tr></thead><tbody><tr><td>是会员？</td><td>Y</td><td>N</td><td>Y</td><td>N</td></tr><tr><td>金额 ≥ 200？</td><td>Y</td><td>Y</td><td>N</td><td>N</td></tr><tr><td><strong>动作</strong> 打 9 折</td><td>✓</td><td></td><td></td><td></td></tr><tr><td>打 95 折</td><td></td><td>✓</td><td>✓</td><td></td></tr><tr><td>不打折</td><td></td><td></td><td></td><td>✓</td></tr></tbody></table><p><strong>验算这张表对不对</strong>：4 列 = 2 个条件各取真假共 <strong>2² = 4 种组合</strong>，无遗漏无双算 ✓。逐列核对规则——(Y,Y)=会员且够钱 → 9 折 ✓；(N,Y)=非会员但够钱 → 命中&quot;金额≥200&quot;→95 折 ✓；(Y,N)=会员但钱不够 → 命中&quot;是会员&quot;→95 折 ✓；(N,N) 两条都不命中 → 不打折 ✓。</p><p><strong>判定树</strong>是判定表的变形，把条件按层级展开：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户是否会员？</span></span>
<span class="line"><span>├─ 是 ── 订单金额 ≥ 200 元？</span></span>
<span class="line"><span>│        ├─ 是 → 打 9 折</span></span>
<span class="line"><span>│        └─ 否 → 打 95 折</span></span>
<span class="line"><span>└─ 否 ── 订单金额 ≥ 200 元？</span></span>
<span class="line"><span>         ├─ 是 → 打 95 折</span></span>
<span class="line"><span>         └─ 否 → 不打折</span></span></code></pre></div><p><strong>两者对照</strong>：<strong>判定树更直观、易理解易用</strong>；<strong>判定表在条件组合多时更严密、不易漏</strong>。口诀&quot;<strong>树好看、表不漏</strong>&quot;。</p><p><strong>结构化语言</strong>则是用 <code>IF…THEN…ELSE</code>、<code>WHILE…DO</code> 这类受限的伪代码写，规则同上例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WHILE (收到出库申请)</span></span>
<span class="line"><span>DO</span></span>
<span class="line"><span>    查询会员信息 AND 查询订单金额;</span></span>
<span class="line"><span>    IF (是会员 AND 金额 ≥ 200)</span></span>
<span class="line"><span>    THEN 打 9 折;</span></span>
<span class="line"><span>    ELSE</span></span>
<span class="line"><span>        IF (金额 ≥ 200 OR 是会员)</span></span>
<span class="line"><span>        THEN 打 95 折;</span></span>
<span class="line"><span>        ELSE 不打折;</span></span>
<span class="line"><span>        ENDIF</span></span>
<span class="line"><span>    ENDIF</span></span>
<span class="line"><span>    生成结算单;</span></span>
<span class="line"><span>ENDDO</span></span></code></pre></div><p><strong>应试动作</strong>：① 背&quot;分层 DFD + 数据词典 + 小说明 + E-R 图&quot;四件套；② 记设计四活动的<strong>依据</strong>（数据设计靠 E-R 图、过程设计管算法）；③ 判定表只需记住&quot;<strong>四区域 + 每列一条规则 + 列数 = 2ⁿ</strong>&quot;，考题问列数就直接算 2 的条件数次方。</p>`,33)])])}const q=s(a,[["render",d]]);export{i as __pageData,q as default};
